import {changesView} from './changes-view.js';
import {escapeHtml as esc} from './agent-view.js';
import {LIVE_STATUSES} from './runtime-client.js';
import {runProgressView} from './progress-view.js';
import {warmupView} from './warmup-view.js';
import {gepaResultsView,gepaOutcome} from './gepa-results-view.js';
import {gepaPlanView,GEPA_PRESETS} from './gepa-plan.js';
const metric=m=>m?`${m.passed} / ${m.total}`:'尚未評測';
export function gepaView(runtime){
 const w=runtime.data?.gepa,run=runtime.selectedGepaRun||w?.latestRun,r=run?.gepaResult,p=run?.gepaProgress;
 const active=['queued','running'].includes(runtime.data?.latestRun?.status),stale=!!runtime.error||!runtime.capabilities||!w||runtime.enabled===false;
 const bankMode=runtime.gepaProfile==='bank',bank=runtime.data?.challenges;
 const disabled=bankMode&&(!bank?.ready||(runtime.data?.provider?.config?.maxTokens??0)<512)||stale||runtime.actionBusy||active||runtime.data?.provider?.busy||!w?.sdk?.available||!w?.optimizer?.available;
 const counts=run?.gepaConfig?.counts||(bankMode?bank?.counts:runtime.gepaProfile==='full'?{train:20,validation:10,heldout:20}:{train:4,validation:2,heldout:4});
 const selected=r?.selectedSkill||p?.selectedSkill,preset=GEPA_PRESETS[bankMode?'bank':runtime.gepaProfile==='full'?'full':'smoke'];
 const approved=w?.versions.some(v=>v.runId===run?.id),eligible=run?.status==='completed'&&r?.checksPassed&&r?.eligible&&!approved&&run?.gepaConfig?.baseline.id===w?.activeVersionId;
 return `<div class="page-heading"><div><p class="eyebrow">REAL GEPA · NANOBOT SDK</p><h1>GEPA 技能最佳化</h1><p>只演化 Python 修復 Skill 本文，以實際工具操作與可信測試評估候選。</p></div><div class="actions"><button class="button secondary" data-live-refresh>↻ 更新狀態</button><button class="button primary" data-gepa-start ${disabled?'disabled':''}>${bankMode?'開始題庫演化':'開始 GEPA 搜尋'}</button>${run&&['queued','running'].includes(run.status)?`<button class="button danger" data-live-cancel="${esc(run.id)}">取消這輪</button>`:''}</div></div>
 <div class="demo-banner"><span class="info-icon">i</span><div><strong>GEPA 0.1.4 × nanobot 0.3.5</strong><span>合成 Python fixture · 任務群組不跨資料分割 · <a href="#challenges">管理多難度題庫</a> · 全新 workspace／session · 僅三個受控工具。最終資料在候選選定後才評測。</span></div><a href="#logs">檢閱模組 Log ↗</a></div>
 ${runtime.actionBusy?'<p class="body-copy" role="status">正在提交操作或重新驗證證據，請稍候…</p>':''}
 ${stale?`<div class="error-banner spaced">${esc(runtime.error||'等待 WSL 本機服務／polling 已暫停')}。請使用 localhost GUI。</div>`:''}
 ${bankMode?`<section class="card spaced" data-bank-execution-scope><h2>下一輪使用：多難度題庫 v${bank?.revision??'待載入'}</h2><p class="body-copy">訓練 ${bank?.counts.train??0} 題／獨立驗證 ${bank?.counts.validation??0} 題／最終測試 ${bank?.counts.heldout??0} 題。按「開始題庫演化」才會提交模型工作。下方成果依其 Run 與資料規模標示；先前的單題修復或 Smoke／Full 成果各自保留。</p></section>`:''}
 ${gepaResultsView(runtime)}
 ${changesView(runtime,run)}
 <section class="card spaced"><h2>搜尋設定</h2><p class="body-copy">SDK：${w?.sdk?.available?'已可用':w?.sdk?.errorCode==='not_probed'?'偵測中，請稍候':'尚未可用'} · GEPA：${w?.optimizer?.available?esc(w.optimizer.version):w?.optimizer?.errorCode==='not_probed'||w?.sdk?.errorCode==='not_probed'?'偵測中，請稍候':'尚未可用'}<br>若偵測完成後仍不可用，請停止 GUI，執行 <code>bash scripts/install-nanobot.sh</code>，再啟動 GUI。先以 Smoke 檢查完整流程；Full 的任務與模型呼叫較多。原本 Smoke／Full 用於流程檢查；要衡量不同 Python 面向，請選擇「多難度題庫」。</p>
 <div class="actions card-actions"><label>資料規模<select data-gepa-profile ${active?'disabled':''}><option value="smoke" ${runtime.gepaProfile==='smoke'||!runtime.gepaProfile?'selected':''}>Smoke · 4 / 2 / 4</option><option value="full" ${runtime.gepaProfile==='full'?'selected':''}>Full · 20 / 10 / 20</option><option value="bank" ${bankMode?'selected':''}>多難度題庫 · ${bank?.counts.train??0} / ${bank?.counts.validation??0} / ${bank?.counts.heldout??0}</option></select></label><label>搜尋評測上限<input data-gepa-metrics type="number" min="${bankMode?2*(bank?.counts.validation??3)+4:runtime.gepaProfile==='full'?26:6}" max="80" value="${runtime.gepaMetrics??preset.metrics}" ${active?'disabled':''}></label><label>候選提案上限<input data-gepa-proposals type="number" min="1" max="8" value="${runtime.gepaProposals??preset.proposals}" ${active?'disabled':''}></label><label>每題呼叫上限（含摘要）<input data-gepa-task-calls type="number" min="2" max="12" value="${runtime.gepaTaskCalls??8}" ${active?'disabled':''}></label><label>整輪上限（秒）<input data-gepa-seconds type="number" min="60" max="7200" value="${runtime.gepaSeconds??preset.seconds}" ${active?'disabled':''}></label><label>單次上限（秒）<input data-gepa-call-seconds type="number" min="10" max="3600" value="${runtime.gepaCallSeconds??120}" ${active?'disabled':''}></label><button class="button secondary" data-live-toggle>${runtime.enabled?'暫停 polling':'繼續 polling'}</button></div>
 ${bankMode?`<p class="small-notice">題庫版本 ${bank?.revision??'待載入'} · <a href="#challenges">新增／編輯／刪除題目 ↗</a>。${bank?.error?esc(bank.error):'每輪使用凍結快照，後續編輯不改變本輪題目。'}${(runtime.data?.provider?.config?.maxTokens??0)<512?'請先在框架整合將最大輸出 tokens 儲存為 1024（至少 512），再開始多難度實驗。':''}</p>`:''}
 ${gepaPlanView(runtime)}
 <p class="body-copy">模型、工具、Skill 名稱／描述與資料版本固定。搜尋預算以每題評測計算；另保留基準／候選各自的獨立驗證與最終評測預算。模型請求不自動重試。</p><p class="body-copy">每題額度包含結尾摘要。例如讀取、基準測試、兩次修正與測試，再產生摘要，共需 7 次模型呼叫。新實驗預設 8 次；全域呼叫上限會隨設定重新計算，整輪與單次時間限制仍會生效。</p></section>
 ${warmupView(runtime.data?.provider,{disabled:!!active||runtime.actionBusy,stale})}${runProgressView(runtime,run)}
 <section class="card spaced" data-gepa-search-progress><div class="progress-details"><span>搜尋評測（上限）</span><strong>${p?.metricEvaluations||r?.metricEvaluations||0} / ${run?.gepaConfig?.metricBudget??runtime.gepaMetrics??preset.metrics}</strong></div><progress value="${p?.metricEvaluations||r?.metricEvaluations||0}" max="${run?.gepaConfig?.metricBudget??runtime.gepaMetrics??preset.metrics}" aria-label="GEPA 搜尋評測"></progress><p class="body-copy">已完成 rollout ${p?.rollouts||r?.rollouts||0} 次 · 提案 ${p?.proposals||r?.proposals||0} 次 · 目前 ${esc(p?.activeTask||'等待')}<br>Train / Validation / Final：${counts?.train??0} / ${counts?.validation??0} / ${counts?.heldout??0} · 題目群組獨立，成果只適用於此合成 fixture。</p></section>
 <section class="card spaced"><div class="card-heading"><div><h2>獨立評測與版本檢閱</h2><p>驗證需改善，最終測試不得退步，才開放核准。核准後只影響未來 GEPA 實驗。</p></div><button class="button primary" data-gepa-approve="${esc(run?.id||'')}" ${!eligible||stale||runtime.actionBusy||active?'disabled':''}>${approved?'已核准':'核准並啟用 Skill'}</button><button class="button secondary" data-gepa-export ${!selected?'disabled':''}>下載候選 SKILL.md</button></div>
 <div class="table-wrap"><table><thead><tr><th>資料分割</th><th>基準成功題數</th><th>候選成功題數</th></tr></thead><tbody>${['validation','heldout'].map(s=>`<tr><td>${s==='validation'?'獨立驗證':'最終測試'}</td><td>${metric(r?.final.baseline[s])}</td><td>${metric(r?.final.selected[s])}</td></tr>`).join('')}</tbody></table></div>
 <p class="body-copy">${r?(gepaOutcome(run).ready?(r.eligible?'已通過版本核准門檻；請檢閱 Skill 差異後操作。':'未通過版本核准門檻；保留目前版本。'):'以下為已保存的評估快照；流程與獨立審查尚未全部完成，不可核准。'):'搜尋結束後固定候選，再獨立測量；完整證據保存於 .local/runs/。'}${r?` · GEPA 評測 ${r.metricEvaluations} 次 · 模型 ${r.calls} 次`:''}</p>
 <div class="diff"><div><div class="diff-heading">基準 Skill</div><pre>${esc(run?.gepaConfig?.baseline.skill.body||w?.active?.skill.body||'等待連線')}</pre></div><div><div class="diff-heading accent">GEPA 選定 Skill${r?` · ${r.selectedSkill.hash===r.baselineSkill.hash?'與基準相同，無新增內容':'Skill 本文已變更，成效見上方獨立評測'}`:''}</div><pre>${esc(selected?.body||'尚未選定')}</pre></div></div></section>
 <section class="card spaced"><h2>Skill 版本</h2><div class="table-wrap"><table><thead><tr><th>版本</th><th>來源 Run</th><th>狀態</th><th>操作</th></tr></thead><tbody>${(w?.versions||[]).map(v=>`<tr><td>${esc(v.label)}</td><td>${esc(v.runId||'初始版本')}</td><td>${v.id===w.activeVersionId?'目前啟用':'已保存'}</td><td><button class="button secondary" data-gepa-activate="${esc(v.id)}" ${v.id===w.activeVersionId||stale||runtime.actionBusy||active?'disabled':''}>啟用／回復</button></td></tr>`).join('')}</tbody></table></div></section>
 <section class="card spaced"><div class="card-heading"><h2>近期 GEPA 實驗</h2><button class="button secondary" data-gepa-select="">查看最新</button></div><div class="table-wrap"><table><thead><tr><th>Run</th><th>流程狀態</th><th>演化成果</th><th>建立時間</th></tr></thead><tbody>${(w?.runs||[]).map(v=>`<tr><td><button class="text-button" data-gepa-select="${esc(v.id)}">${esc(v.id)}</button></td><td>${esc(LIVE_STATUSES[v.status])}</td><td>${esc(v.id===run?.id?gepaOutcome(run).label:'點選 Run 檢閱')}</td><td>${esc(v.createdAt)}</td></tr>`).join('')||'<tr><td colspan="4">尚無紀錄</td></tr>'}</tbody></table></div></section>`;
}
